use super::{layout, parse_import_line, split_head, ImportSpec};

/// Pull the import block out of a canonically-shaped module: returns the module carrying only its
/// doc-comment + body (exactly what a migrated record would STORE) and the specs the block encoded.
/// `body_with_imports(&stripped, &specs)` then reproduces the original byte for byte — the identity
/// `strip_and_body_with_imports_are_exact_inverses` pins. This is the READ half the graph-side
/// `normalize`/`migrate` verbs call.
pub fn strip_imports(code: &str) -> (String, Vec<ImportSpec>) {
    let (head, after_head) = split_head(code);
    let mut specs = Vec::new();
    let mut idx = 0usize;
    for line in after_head.split_inclusive('\n') {
        if let Some(s) = parse_import_line(line) {
            specs.push(s);
            idx += line.len();
        } else if line.trim().is_empty() && !specs.is_empty() {
            // the blank line terminating the block: consume it and stop.
            idx += line.len();
            break;
        } else {
            break;
        }
    }
    let body = after_head[idx..].trim_start_matches(['\n', '\r']);
    (layout(head, "", body), specs)
}
